sc_cat_item_producer.script:
(function executeProducer(current, producer) {
    // Map user inputs (make sure these names match your variables & table fields)
    current.setValue('name',          producer.name);
    current.setValue('e_mail',        producer.e_mail);      // use your exact variable name
    current.setValue('phonenumber',   producer.phonenumber);
    current.setValue('location',      producer.location);
    current.setValue('service_type',  producer.service_type);
    current.setValue('description', producer.description);

    // Force feedback type to "complaint" on every record
    current.setValue('feedback_type', 'complaint'); // value, not label
})(current, producer);
